export const ORGANIC_STILL_W = 168;
export const ORGANIC_STILL_H = 168;

let cached: Uint8ClampedArray | null = null;

function pixels(): Uint8ClampedArray {
  if (cached) return cached;
  const raw = atob(B64);
  const rgba = new Uint8ClampedArray(112896);
  for (let i = 0, p = 0; i < raw.length; i += 3, p += 4) {
    rgba[p] = raw.charCodeAt(i);
    rgba[p + 1] = raw.charCodeAt(i + 1);
    rgba[p + 2] = raw.charCodeAt(i + 2);
    rgba[p + 3] = 255;
  }
  cached = rgba;
  return rgba;
}

/** Synchronous. The card paints this on mount, before the browser's first frame. */
export function paintOrganicStill(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  if (canvas.width !== ORGANIC_STILL_W) canvas.width = ORGANIC_STILL_W;
  if (canvas.height !== ORGANIC_STILL_H) canvas.height = ORGANIC_STILL_H;
  const image = ctx.createImageData(ORGANIC_STILL_W, ORGANIC_STILL_H);
  image.data.set(pixels());
  ctx.putImageData(image, 0, 0);
}
